-- Generated by scripts/dump_schema.py from app/models.py. The app also runs create_all() on startup.

CREATE TABLE batches (
	id UUID NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	status VARCHAR(20) DEFAULT 'PROCESSING' NOT NULL, 
	total_docs INTEGER NOT NULL, 
	completed_count INTEGER DEFAULT '0' NOT NULL, 
	failed_count INTEGER DEFAULT '0' NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	completed_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

CREATE TABLE jobs (
	id UUID NOT NULL, 
	batch_id UUID NOT NULL, 
	filename VARCHAR(300) NOT NULL, 
	status VARCHAR(12) DEFAULT 'PENDING' NOT NULL, 
	attempts INTEGER DEFAULT '0' NOT NULL, 
	max_attempts INTEGER DEFAULT '3' NOT NULL, 
	error TEXT, 
	worker_id VARCHAR(100), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE, 
	finished_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(batch_id) REFERENCES batches (id) ON DELETE CASCADE
);

CREATE INDEX ix_jobs_batch_status ON jobs (batch_id, status);

CREATE TABLE documents (
	job_id UUID NOT NULL, 
	content_type VARCHAR(100) NOT NULL, 
	data BYTEA NOT NULL, 
	ground_truth JSONB, 
	PRIMARY KEY (job_id), 
	FOREIGN KEY(job_id) REFERENCES jobs (id) ON DELETE CASCADE
);

CREATE TABLE extraction_results (
	job_id UUID NOT NULL, 
	fields JSONB NOT NULL, 
	confidence FLOAT NOT NULL, 
	extracted_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (job_id), 
	FOREIGN KEY(job_id) REFERENCES jobs (id) ON DELETE CASCADE
);

CREATE TABLE job_events (
	id BIGSERIAL NOT NULL, 
	job_id UUID NOT NULL, 
	event VARCHAR(30) NOT NULL, 
	detail TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(job_id) REFERENCES jobs (id) ON DELETE CASCADE
);

CREATE INDEX ix_job_events_job_id ON job_events (job_id);
